)
INSERT INTO "Configuration" (carepartner_id, module_id, occurence_type, occurence_definition, position, duration) 
SELECT carepartner_id, module_id, 'daily', ARRAY[]::integer[], ROW_NUMBER() OVER (ORDER BY module_id), 30
FROM modules_insert;